export const hostToolDescriptions = {"concord_work_start":"Use for implementation work from a default checkout, or to resume an existing item by work_id. Capture new work, reuse an active worktree, or bootstrap the missing canonical worktree. A successful claim moves the session automatically and verifies the landing; vacate returns it to the registered main; never claim from a default checkout. Resume takes only work_id and claims in the calling session's Project; another Project here uses worktree_claim; another repository needs a host-started session.","concord_ci_watch":"Start watching GitHub CI and return at once: the concord ci-wait verb runs as a plugin-owned child with zero model turns, and this session receives the terminal JSON report as a message when the wait ends. Pass repo (owner/name), one selector (kind pr, sha, or run with its value), and optionally mode (checks or merge) and time_seconds_max. After a push to the pull request, also pass head_sha, the pushed commit: the wait then judges that commit, never the head it replaces.","concord_worker_read":"Read one byte page of an original declared pinned reading for the calling dispatched worker. Supply only ordinal, offset, and length. The host binds the active packet, attempt, and worktree. Returns source identity, whole-content hash, byte offsets, EOF, base64 data, and text when the page is complete UTF-8. No path, ref, packet replacement, state query, workflow authority, or changed-checkout fallback.","concord_worker_diff":"Read one byte page of the authorized review's committed diff. Supply only offset and length. The host binds the first editing dispatch subject under this contract, the held review subject, and the pinned job's literal path scope. Returns both commits, whole-diff hash, byte offsets, EOF, base64 data, and text when the page is complete UTF-8. No worker-selected path or ref, replacement packet, mutable-checkout fallback, or workflow authority.","concord_worker_check":"Execute one recorded native control for the calling authorized worker. Supply only control_id from the original worker job's acceptance_oracle.controls. The host binds the actual child, packet, job, preparation, subject, and worktree and returns the existing native producer's result. Ordinary job checks strings are requirements, not executable controls. No argv, cwd, runner, state inventory, or workflow authority."} as const;
export const hostToolSchemas = {"concord_work_start":{"oneOf":[{"additionalProperties":false,"properties":{"defect_intake":{"additionalProperties":false,"description":"Capture admission record for defects: required for kind bug, optional for kind research, refused for every other kind (the core enforces the kind rules and the admission decision). failure_shape is a canonical bounded slug identifier repeated on every capture of the defect class; reproduction and searched are bounded nonempty text; related_defect_ids declares distinct earlier work IDs of the same shape and may be empty; root_cause_work_id names the completed workflow.research cluster RCA a recurrent bug capture needs.","properties":{"failure_shape":{"maxLength":64,"minLength":1,"pattern":"^[a-z0-9][a-z0-9-]{0,63}$","type":"string"},"related_defect_ids":{"items":{"maxLength":128,"minLength":1,"pattern":"^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$","type":"string"},"maxItems":20,"type":"array","uniqueItems":true},"reproduction":{"maxLength":8192,"minLength":1,"type":"string","x-maxBytes":8192},"root_cause_work_id":{"maxLength":128,"minLength":1,"pattern":"^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$","type":"string"},"searched":{"maxLength":8192,"minLength":1,"type":"string","x-maxBytes":8192}},"required":["failure_shape","reproduction","searched","related_defect_ids"],"type":"object"},"external_ref":{"maxLength":256,"minLength":1,"type":"string","x-maxBytes":256},"governing_requirements":{"items":{"maxLength":128,"minLength":1,"pattern":"^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$","type":"string"},"maxItems":32,"type":"array","uniqueItems":true},"idempotency_key":{"maxLength":128,"minLength":1,"pattern":"^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$","type":"string"},"kind":{"enum":["task","bug","decision","research","other"],"type":"string"},"priority":{"maximum":100,"minimum":-100,"type":"integer"},"raised_from_work_id":{"maxLength":128,"minLength":1,"pattern":"^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$","type":"string"},"ref":{"maxLength":128,"minLength":1,"type":"string"},"size_inputs":{"additionalProperties":false,"description":"What this change will touch, for the work-item size model (CD-0229 D4). Name the files, a behavior phrase, or both. The tool derives kind, stage, audience, Domains, packages, and repositories; the model decides the size. There is no size field: a proposed size is refused.","properties":{"behavior":{"description":"A phrase for the behavior the change will alter, when the files are not known yet.","maxLength":256,"minLength":1,"type":"string"},"blast_radius":{"description":"The widest thing a defect could break: one function, one package, several packages, or a public surface (CLI, tool, schema, wire format).","enum":["contained","package","cross_package","external"],"type":"string"},"estimated_production_lines":{"description":"Production lines you expect to add or change, tests excluded.","maximum":100000,"minimum":1,"type":"integer"},"paths":{"description":"Repository-relative files or directories the change will edit.","items":{"maxLength":512,"minLength":1,"type":"string"},"maxItems":64,"type":"array","uniqueItems":true},"security":{"description":"True when the change touches authentication, authorization, secrets, or data safety.","type":"boolean"},"user_visible":{"description":"True when the change removes or reverses behavior users see, or changes UI or UX.","type":"boolean"}},"required":["security","user_visible","blast_radius","estimated_production_lines"],"type":"object"},"tags":{"items":{"maxLength":128,"minLength":1,"pattern":"^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$","type":"string"},"maxItems":32,"type":"array","uniqueItems":true},"task":{"maxLength":8192,"minLength":1,"type":"string","x-maxBytes":8192},"title":{"maxLength":256,"minLength":1,"type":"string","x-maxBytes":256},"urgency":{"enum":["standard","expedite"],"type":"string"},"value_statement":{"maxLength":256,"minLength":1,"type":"string","x-maxBytes":256},"workflow_type_ref":{"maxLength":128,"minLength":1,"pattern":"^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$","type":"string"}},"required":["title","value_statement","kind","task","idempotency_key"]},{"additionalProperties":false,"properties":{"work_id":{"maxLength":128,"minLength":1,"pattern":"^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$","type":"string"}},"required":["work_id"]}],"type":"object"},"concord_ci_watch":{"type":"object","properties":{"repo":{"type":"string","description":"GitHub repository as owner/name.","pattern":"^[A-Za-z0-9][A-Za-z0-9.-]*/[A-Za-z0-9][A-Za-z0-9.-]*$","minLength":3,"maxLength":256},"selector":{"type":"object","description":"One CI selector: kind pr, sha, or run, with its value.","additionalProperties":false,"required":["kind","value"],"properties":{"kind":{"type":"string","enum":["pr","sha","run"]},"value":{"type":"string","minLength":1,"maxLength":64}}},"head_sha":{"type":"string","description":"For a pr selector: the commit to judge, usually the one just pushed. The wait stays pending until the pull request head reaches it.","pattern":"^[0-9a-f]{40}$"},"mode":{"type":"string","description":"Wait mode: checks (default) or merge.","enum":["checks","merge"]},"time_seconds_max":{"type":"integer","description":"Maximum wait budget in seconds; the default is 1800.","minimum":0,"maximum":1800}},"required":["repo","selector"],"additionalProperties":false},"concord_worker_read":{"type":"object","additionalProperties":false,"properties":{"ordinal":{"type":"integer","minimum":0,"maximum":9007199254740991,"description":"Zero-based index in the original packet's required_reading list."},"offset":{"type":"integer","minimum":0,"maximum":9007199254740991,"description":"Nonnegative raw-byte offset."},"length":{"type":"integer","minimum":1,"maximum":4096,"description":"Page length in raw bytes, from 1 through 4096."}},"required":["ordinal","offset","length"]},"concord_worker_diff":{"type":"object","additionalProperties":false,"properties":{"offset":{"type":"integer","minimum":0,"maximum":9007199254740991,"description":"Nonnegative raw-byte offset."},"length":{"type":"integer","minimum":1,"maximum":4096,"description":"Page length in raw bytes, from 1 through 4096."}},"required":["offset","length"]},"concord_worker_check":{"type":"object","additionalProperties":false,"properties":{"control_id":{"type":"string","minLength":1,"maxLength":128,"x-minBytes":2,"x-maxBytes":128,"pattern":"^[^\\x09-\\x0d    -     　]+$","description":"The exact recorded control identifier, with no Unicode whitespace and 2-128 UTF-8 bytes."}},"required":["control_id"]}} as const;
